export type ChecklistStepStatus = "idle" | "complete" | "skipped";

export interface ChecklistStep {
  id: string;
  title: string;
  description?: string;
  cta?: string; // action button label
  onAction?: () => void; // called when CTA is clicked
  href?: string; // navigate instead of onAction
  requires?: string[]; // ids that must be complete first
  optional?: boolean;
}

export interface ChecklistConfig {
  title?: string;
  subtitle?: string;
  storageKey?: string; // localStorage key for persistence
  position?: "bottom-right" | "bottom-left" | "inline";
}

export interface ChecklistContextValue {
  steps: ChecklistStep[];
  statuses: Record<string, ChecklistStepStatus>;
  isOpen: boolean;
  completedCount: number;
  requiredCount: number;
  progress: number; // 0–100
  isComplete: boolean;
  complete: (id: string) => void;
  skip: (id: string) => void;
  undo: (id: string) => void;
  open: () => void;
  close: () => void;
  toggle: () => void;
  canActivate: (id: string) => boolean;
}

"use client";

import * as React from "react";
import type { ChecklistContextValue } from "./types";

export const ChecklistCtx = React.createContext<ChecklistContextValue | null>(null);

export function useChecklist(): ChecklistContextValue {
  const ctx = React.useContext(ChecklistCtx);
  if (!ctx) throw new Error("useChecklist must be used inside ChecklistRoot");
  return ctx;
}

"use client";

import * as React from "react";
import { ChecklistCtx } from "./checklist-context";
import { ChecklistWidget } from "./checklist-widget";
import type {
  ChecklistStep,
  ChecklistConfig,
  ChecklistContextValue,
  ChecklistStepStatus,
} from "./types";

export interface ChecklistRootProps {
  steps: ChecklistStep[];
  config?: ChecklistConfig;
  children?: React.ReactNode;
}

export function ChecklistRoot({
  steps,
  config = {},
  children,
}: ChecklistRootProps) {
  const key = config.storageKey ?? "bevel-checklist";

  const [statuses, setStatuses] = React.useState<
    Record<string, ChecklistStepStatus>
  >(() => {
    if (typeof window === "undefined") return {};
    try {
      return JSON.parse(localStorage.getItem(key) ?? "{}");
    } catch {
      return {};
    }
  });

  const [isOpen, setIsOpen] = React.useState(false);

  // Persist on every change
  React.useEffect(() => {
    try {
      localStorage.setItem(key, JSON.stringify(statuses));
    } catch {}
  }, [statuses, key]);

  const requiredCount = steps.filter((s) => !s.optional).length;
  const completedCount = steps.filter(
    (s) => statuses[s.id] === "complete",
  ).length;
  const progress =
    requiredCount === 0
      ? 100
      : Math.round((completedCount / requiredCount) * 100);
  const isComplete = completedCount >= requiredCount;

  function canActivate(id: string): boolean {
    const step = steps.find((s) => s.id === id);
    if (!step?.requires?.length) return true;
    return step.requires.every((rid) => statuses[rid] === "complete");
  }

  function complete(id: string) {
    setStatuses((p) => ({ ...p, [id]: "complete" }));
  }

  function skip(id: string) {
    setStatuses((p) => ({ ...p, [id]: "skipped" }));
  }

  function undo(id: string) {
    setStatuses((p) => ({ ...p, [id]: "idle" }));
  }

  const ctx: ChecklistContextValue = {
    steps,
    statuses,
    isOpen,
    completedCount,
    requiredCount,
    progress,
    isComplete,
    complete,
    skip,
    undo,
    open: () => setIsOpen(true),
    close: () => setIsOpen(false),
    toggle: () => setIsOpen((p) => !p),
    canActivate,
  };

  return (
    <ChecklistCtx.Provider value={ctx}>
      {children}
      {config.position !== "inline" && <ChecklistWidget config={config} />}
    </ChecklistCtx.Provider>
  );
}

ChecklistRoot.displayName = "ChecklistRoot";

import * as React from "react";

export function ChecklistProgressRing({
  progress,
  size = 44,
  strokeWidth = 3,
}: {
  progress: number;
  size?: number;
  strokeWidth?: number;
}) {
  const r   = (size - strokeWidth * 2) / 2;
  const c   = 2 * Math.PI * r;
  const off = c - (progress / 100) * c;

  return (
    <svg width={size} height={size} style={{ transform: "rotate(-90deg)" }}>
      <circle
        cx={size / 2} cy={size / 2} r={r}
        fill="none" stroke="currentColor" strokeWidth={strokeWidth}
        className="text-muted/40"
      />
      <circle
        cx={size / 2} cy={size / 2} r={r}
        fill="none" stroke="currentColor" strokeWidth={strokeWidth}
        strokeDasharray={c}
        strokeDashoffset={off}
        className="text-primary transition-all duration-500"
        strokeLinecap="round"
      />
    </svg>
  );
}

"use client";

import * as React from "react";
import { useChecklist } from "./checklist-context";
import { Button } from "@/components/ui/button";
import {
  IconCheck,
  IconMinus,
  IconLock,
  IconRotate,
} from "@tabler/icons-react";
import { cn } from "@/lib/utils";
import type { ChecklistStep } from "./types";

export function ChecklistItem({ step }: { step: ChecklistStep }) {
  const { statuses, complete, skip, undo, canActivate } = useChecklist();
  const status = statuses[step.id] ?? "idle";
  const active = canActivate(step.id);
  const isDone = status === "complete";
  const isSkipped = status === "skipped";
  const isLocked = !active && status === "idle";

  function handleAction() {
    if (!active) return;
    if (step.onAction) {
      step.onAction();
      complete(step.id);
    } else if (step.href) {
      window.open(step.href, "_blank");
      complete(step.id);
    } else complete(step.id);
  }

  return (
    <div
      className={cn(
        "flex items-start gap-3 px-4 py-3 rounded-md transition-colors",
        !isDone && !isSkipped && active && "hover:bg-muted/30",
        (isDone || isSkipped) && "opacity-60",
      )}
    >
      {/* Status icon */}
      <button
        type="button"
        onClick={() =>
          isDone || isSkipped
            ? undo(step.id)
            : active
              ? complete(step.id)
              : undefined
        }
        disabled={isLocked}
        className={cn(
          "w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 mt-0.5 transition-all",
          isDone && "bg-primary border-primary",
          isSkipped && "border-muted-foreground/30",
          !isDone &&
            !isSkipped &&
            active &&
            "border-border hover:border-primary",
          isLocked && "border-muted/30 cursor-not-allowed",
        )}
      >
        {isDone && (
          <IconCheck size={11} strokeWidth={2.5} className="text-black" />
        )}
        {isSkipped && (
          <IconMinus
            size={11}
            strokeWidth={2}
            className="text-muted-foreground/50"
          />
        )}
        {isLocked && (
          <IconLock
            size={9}
            strokeWidth={2}
            className="text-muted-foreground/20"
          />
        )}
      </button>

      {/* Content */}
      <div className="flex-1 min-w-0">
        <p
          className={cn(
            "text-[13px] font-medium leading-snug",
            isDone || isSkipped
              ? "line-through text-muted-foreground/50"
              : "text-foreground",
          )}
        >
          {step.title}
        </p>
        {step.description && !isDone && !isSkipped && (
          <p className="text-[11px] text-muted-foreground/60 mt-0.5 leading-relaxed">
            {step.description}
          </p>
        )}

        {/* Actions */}
        {!isDone &&
          !isSkipped &&
          active &&
          (step.cta || step.onAction || step.href) && (
            <div className="flex items-center gap-2 mt-2">
              <Button
                variant="outline"
                size="sm"
                onClick={handleAction}
                className="h-7 text-[11px]"
              >
                {step.cta ?? "Get started"}
              </Button>
              {step.optional && (
                <button
                  type="button"
                  onClick={() => skip(step.id)}
                  className="text-[11px] text-muted-foreground/40 hover:text-muted-foreground transition-colors"
                >
                  Skip
                </button>
              )}
            </div>
          )}
      </div>

      {/* Undo for done */}
      {isDone && (
        <button
          type="button"
          onClick={() => undo(step.id)}
          className="text-muted-foreground/60 hover:text-muted-foreground transition-colors mt-0.5 shrink-0 cursor-pointer"
          title="Mark incomplete"
        >
          <IconRotate size={12} />
        </button>
      )}
    </div>
  );
}

ChecklistItem.displayName = "ChecklistItem";

"use client";

import * as React from "react";
import { motion, AnimatePresence } from "motion/react";
import { useChecklist } from "./checklist-context";
import { ChecklistItem } from "./checklist-item";
import { ChecklistProgressRing } from "./checklist-progress-ring";
import { IconX, IconSparkles } from "@tabler/icons-react";
import { cn } from "@/lib/utils";
import type { ChecklistConfig } from "./types";

export function ChecklistWidget({ config }: { config: ChecklistConfig }) {
  const {
    steps,
    isOpen,
    toggle,
    close,
    progress,
    completedCount,
    requiredCount,
    isComplete,
  } = useChecklist();

  const posClass =
    config.position === "bottom-left" ? "left-6 bottom-6" : "right-6 bottom-6";

  return (
    <div className={cn("fixed z-50 flex flex-col items-end gap-3", posClass)}>
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 12, scale: 0.96 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 12, scale: 0.96 }}
            transition={{ duration: 0.18, ease: "easeOut" }}
            className="w-80 rounded-xl border border-border bg-card shadow-2xl shadow-black/40 overflow-hidden p-1"
          >
            {/* Header */}
            <div className="flex items-center justify-between px-4 pt-4 pb-3 border-b border-border/60">
              <div className="flex flex-col gap-0.5">
                <span className="text-[13px] font-semibold text-foreground">
                  {config.title ?? "Get started"}
                </span>
                {config.subtitle && (
                  <span className="text-[11px] text-muted-foreground/60">
                    {config.subtitle}
                  </span>
                )}
              </div>
              <button
                type="button"
                onClick={close}
                className="text-muted-foreground/40 hover:text-foreground transition-colors"
              >
                <IconX size={14} />
              </button>
            </div>

            {/* Progress bar */}
            <div className="px-4 py-2.5 border-b border-border/40">
              <div className="flex items-center justify-between mb-1.5">
                <span className="text-[10px] font-mono text-muted-foreground/50 uppercase tracking-wider">
                  {completedCount} of {requiredCount} complete
                </span>
                <span className="text-[10px] font-mono text-primary/70">
                  {progress}%
                </span>
              </div>
              <div className="h-1 bg-muted/50 rounded-full overflow-hidden">
                <motion.div
                  className="h-full bg-primary rounded-full"
                  initial={{ width: 0 }}
                  animate={{ width: `${progress}%` }}
                  transition={{ duration: 0.4, ease: "easeOut" }}
                />
              </div>
            </div>

            {/* Steps */}
            {isComplete ? (
              <div className="flex flex-col items-center gap-2 py-8 px-4">
                <div className="w-10 h-10 rounded-full bg-primary/15 border border-primary/30 flex items-center justify-center">
                  <IconSparkles size={18} className="text-primary" />
                </div>
                <p className="text-[13px] font-semibold text-foreground">
                  You're all set
                </p>
                <p className="text-[11px] text-muted-foreground/60 text-center">
                  All steps completed. You're ready to go.
                </p>
              </div>
            ) : (
              <div className="flex flex-col divide-y divide-border/40 py-1 max-h-72 overflow-y-auto space-y-1">
                {steps.map((step) => (
                  <ChecklistItem key={step.id} step={step} />
                ))}
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Floating trigger */}
      <motion.button
        type="button"
        onClick={toggle}
        whileHover={{ scale: 1.05 }}
        whileTap={{ scale: 0.95 }}
        className="relative flex items-center justify-center w-12 h-12 rounded-full bg-card border border-border shadow-lg shadow-black/30 hover:border-primary/40 transition-colors"
        title="Setup checklist"
      >
        <ChecklistProgressRing
          progress={progress}
          size={44}
          strokeWidth={2.5}
        />
        <span className="absolute text-[10px] font-bold text-primary tabular-nums">
          {completedCount}/{requiredCount}
        </span>
      </motion.button>
    </div>
  );
}

ChecklistWidget.displayName = "ChecklistWidget";

export { ChecklistRoot }        from "./checklist-root";
export { ChecklistItem }        from "./checklist-item";
export { ChecklistWidget }      from "./checklist-widget";
export { ChecklistProgressRing } from "./checklist-progress-ring";
export { useChecklist }         from "./checklist-context";
export type { ChecklistStep, ChecklistConfig, ChecklistStepStatus } from "./types";
